export function getDefaultSectionsForAgeGroup(ageGroup) {
  const str = String(ageGroup || "").trim().toLowerCase();
  if (str.includes("1-2") || str.includes("1–2")) return ECE_OFFICIAL_QUESTION_BANKS["1-2"] || [];
  if (str.includes("2-3") || str.includes("2–3") || str.includes("play")) return ECE_OFFICIAL_QUESTION_BANKS["2-3"] || [];
  if (str.includes("3-4") || str.includes("3–4") || str.includes("nursery")) return ECE_OFFICIAL_QUESTION_BANKS["3-4"] || [];
  if (str.includes("4-5") || str.includes("4–5") || str.includes("jr") || str.includes("junior")) return ECE_OFFICIAL_QUESTION_BANKS["4-5"] || [];
  if (str.includes("5-6") || str.includes("5–6") || str.includes("sr") || str.includes("senior")) return ECE_OFFICIAL_QUESTION_BANKS["5-6"] || [];
  return ECE_OFFICIAL_QUESTION_BANKS["2-3"] || [];
}
